+func readEntityMgmtSecret() (string, error) {
+	arn := os.Getenv(app.ConfigEntityMgmtSecretARN)
+	if arn == "" {
+		panic(app.ConfigEntityMgmtSecretARN + " env not setup")
+	}
+
+	if config.Environment == config.EnvironmentDevelopment {
+		// dev: env var holds the secret value directly
+		return arn, nil
+	}
+
+	c, cancel := context.WithTimeout(context.Background(), 5*time.Second)
+	defer cancel()
+
+	sm := initSecretsManager()
+	output, err := sm.GetSecretValue(c, &secretsmanager.GetSecretValueInput{
+		SecretId: &arn,
+	})
+	if err != nil {
+		return "", errors.Wrap(err, errors.CodeInternalServerError,
+			"Failed to get entity-management secret from Secrets Manager")
+	}
+	if output.SecretString == nil {
+		return "", errors.New(errors.CodeInternalServerError,
+			"entity-management secret is not setup in Secrets Manager")
+	}
+	return *output.SecretString, nil
+}

