+func TestCalculateRequestHmac_DifferentInputs(t *testing.T) {
+	base := calculateRequestHmac("s", "1", "GET", "/x", "")
+	cases := map[string]string{
+		"timestamp change": calculateRequestHmac("s", "2", "GET", "/x", ""),
+		"secret change":    calculateRequestHmac("other", "1", "GET", "/x", ""),
+		"method change":    calculateRequestHmac("s", "1", "POST", "/x", ""),
+		"url change":       calculateRequestHmac("s", "1", "GET", "/y", ""),
+		"body change":      calculateRequestHmac("s", "1", "GET", "/x", "b"),
+	}
+	for name, got := range cases {
+		if got == base {
+			t.Errorf("%s did not change hmac (both = %s)", name, got)
+		}
+	}
